"""
NOEFS protocol data tool for official DLED (zhyczy/DLED @ b8c41ea).

  build : assemble DF40_FF_train_NOEFS.json and DF40_FF_test_NOFE_all.json
          from DF40's per-method JSON files.
  audit : load both with the OFFICIAL loader's own collection + balancing code
          and check every candidate image exists. Writes missing paths per method.

Why both are needed
  * DF40_FF_test_NOFE_all  -- generated by preprocessing/merge_seen_unseen.py.
    `build` reproduces that script's method list and 'test' split exactly.
  * DF40_FF_train_NOEFS    -- requested by train.sh but NO script in the repo
    generates this name (organize_json.py only makes DF40_mixed_train_NOEFS).
    `build` RECONSTRUCTS it using organize_json.py's NOEFS training method list
    (5 seen FS + 5 seen FR) with the *_ff* JSONs and the 'train' split.
    This is an inference -> document it; confirm with the authors if possible.
  * The loader silently substitutes sample 0 for any unreadable image
    (frequency_dateset.py __getitem__), so a partial dataset trains without
    error. `audit` is the guard against that. Do not train until it reports 0
    missing.

MidJourney: the official preprocessing/change_json_path.py converts its GIFs to
PNG, rewrites .gif->.png in the paths and drops 5 broken images. `build` applies
the path rule and the drops; run `gif2png` once to convert the files on disk.
The other rules in that script do not affect NOEFS or are equivalent to our
folder names (whichisreal, rddm).

Usage (from the repo root, after `source repro/env.sh`):
  python repro/noefs_data.py build --src $DLED_DATA/df40_json \
         --dst $DLED_DATA/DF40/json_file
  python repro/noefs_data.py gif2png
  python repro/noefs_data.py audit --json $DLED_DATA/DF40/json_file \
         --out $DLED_DATA/audit
"""
import argparse
import collections
import json
import os
import random
import sys

# --- method lists copied from the official preprocessing scripts ----------
# organize_json.py, '_NOEFS' training filter (used with *_mixed there)
TRAIN_NOEFS = ['fsgan', 'faceswap', 'simswap', 'inswap', 'blendface',     # FS seen
               'fomm', 'facevid2vid', 'wav2lip', 'MRAA', 'one_shot_free']  # FR seen
# merge_seen_unseen.py, 'DF40_FF_test_NOFE_all' test filter (verbatim)
TEST_NOFE_ALL = [
    'fomm_ff', 'facevid2vid_ff', 'wav2lip_ff', 'MRAA_ff', 'one_shot_free_ff',
    'VQGAN_ff', 'StyleGAN2_ff', 'StyleGAN3_ff', 'StyleGANXL_ff', 'sd2.1_ff',
    'fsgan_ff', 'faceswap_ff', 'simswap_ff', 'inswap_ff', 'blendface_ff',
    'pirender_ff', 'tpsm_ff', 'lia_ff', 'danet_ff', 'sadtalker_ff', 'mcnet_ff',
    'hyperreenact_ff', 'heygen',
    'ddim_ff', 'rddm_ff', 'pixart_ff', 'DiT_ff', 'SiT_ff', 'MidJourney', 'whichisreal',
    'uniface_ff', 'mobileswap_ff', 'e4s_ff', 'facedancer_ff', 'deepfacelab']


# --- MidJourney fix-up copied from the official preprocessing/change_json_path.py:
# paths .gif -> .png (the GIFs are converted on disk, see `gif2png`) and these
# five images are dropped from the index.
MJ_DROP = {
    '13592447708_Single_person_East_Asian_male_looking_at_the_camera_75e759ff-c23a-4679-bd68-76170370d3d1.png',
    '13592447708_Single_person_white_female_looking_at_the_camera_fa_72edc876-2d1f-41b6-b7cb-caaa907da5ab.png',
    '13592447708_Clean_East_Asian_female_face_face_only_shown_face_c_ba354e74-3cb4-4f63-9ad6-f40a641b558a.png',
    '13592447708_Clean_East_Asian_male_face_only_face_shown_close-up_3ad609fd-9d87-4242-9d5b-d2776a3c2c7e.png',
    '13592447708_Single_person_white_female_looking_at_the_camera_fa_d28fc222-bd3f-4ee6-ad9f-7af441607d82.png',
}


def fix_midjourney(data):
    """Apply change_json_path.py's MidJourney rule in place; return #dropped."""
    dropped = 0
    for spec in data['MidJourney'].values():
        for split in spec.values():
            for video in split.values():
                kept = []
                for p in video['frames']:
                    q = p.replace('.gif', '.png')
                    if os.path.basename(q) in MJ_DROP and '/MidJourney/fake/' in q:
                        dropped += 1
                        continue
                    kept.append(q)
                video['frames'] = kept
    return dropped


def gif2png(data_root):
    """Official step (end of change_json_path.py): save each MidJourney .gif as .png (PIL)."""
    from PIL import Image
    d = os.path.join(data_root, 'DF40', 'MidJourney', 'fake')
    n = 0
    for fn in sorted(os.listdir(d)):
        if fn.endswith('.gif'):
            out = os.path.join(d, fn[:-4] + '.png')
            if not os.path.exists(out):
                Image.open(os.path.join(d, fn)).save(out, 'PNG')
                n += 1
    print(f'converted {n} GIFs to PNG in {d}')


def build(src, dst):
    os.makedirs(dst, exist_ok=True)
    plan = {
        'DF40_FF_train_NOEFS': ([m + '_ff' for m in TRAIN_NOEFS], 'train'),
        'DF40_FF_test_NOFE_all': (TEST_NOFE_ALL, 'test'),
    }
    for out_name, (files, split) in plan.items():
        merged, missing = {}, []
        for fn in files:
            p = os.path.join(src, fn + '.json')
            if not os.path.exists(p):
                missing.append(fn)
                continue
            with open(p, encoding='utf-8') as f:
                data = json.load(f)
            if fn not in data:
                sys.exit(f'{p}: top-level key {fn!r} not found (keys: {list(data)[:5]})')
            if fn == 'MidJourney':
                print(f'  MidJourney: .gif->.png, dropped {fix_midjourney(data)} listed frames '
                      '(official change_json_path.py rule)')
            for set_key, spec in data[fn].items():        # e.g. fsgan_Real / fsgan_Fake
                if set_key in merged:
                    print(f'  WARNING {out_name}: {set_key} appears twice; last wins (official behaviour)')
                merged[set_key] = {split: spec[split]}
        if missing:
            sys.exit(f'{out_name}: missing source JSONs: {missing}')
        with open(os.path.join(dst, out_name + '.json'), 'w') as f:
            json.dump({out_name: merged}, f, indent=1)
        n_vid = sum(len(v[split]) for v in merged.values())
        print(f'{out_name}: {len(merged)} label keys, {n_vid} videos/items -> {dst}')


READABLE = {'.png', '.jpg', '.jpeg', '.bmp'}


def audit(json_dir, out_dir, max_per_cls=13504, seed=1024):
    import numpy as np
    import yaml
    sys.path[:0] = [os.getcwd(), os.path.join(os.getcwd(), 'training')]
    from dataset.frequency_dateset import DeepfakeFrequencyDataset as D

    with open('training/config/detector/dled.yaml') as f:
        cfg = yaml.safe_load(f)
    with open('training/config/train_config.yaml') as f:
        cfg.update(yaml.safe_load(f))
    cfg.update(dataset_json_folder=json_dir, max_samples_per_class=max_per_cls,
               training_data_ratio=1.0, detect_novel=False)
    cfg['backbone_config']['num_classes'] = 3
    print('DF40_OLD_ROOT =', os.environ.get('DF40_OLD_ROOT'),
          '| DF40_DATA_ROOT =', os.environ.get('DF40_DATA_ROOT'))
    os.makedirs(out_dir, exist_ok=True)
    total_missing = 0

    for name, mode in [('DF40_FF_train_NOEFS', 'train'), ('DF40_FF_test_NOFE_all', 'test')]:
        random.seed(seed); np.random.seed(seed)
        ds = D.__new__(D)                     # official methods, no __init__ side effects
        ds.config, ds.mode = cfg, mode
        ds.compression, ds.frame_num = cfg['compression'], cfg['frame_num'][mode]
        ds.video_level, ds.clip_size, ds.lmdb = False, None, False
        paths, labels, vids = ds.collect_img_and_label_for_one_dataset(name)

        per_method = collections.defaultdict(lambda: [0, 0])  # method -> [n, missing]
        miss_by_method = collections.defaultdict(list)
        for p, v in zip(paths, vids):
            method = v.split('_')[0] if not v.startswith('one_shot') else 'one_shot_free'
            per_method[method][0] += 1
            # OpenCV (the official loader's reader) cannot decode GIF; the loader
            # would silently substitute sample 0, so count those as missing too.
            if not os.path.isfile(p) or os.path.splitext(p)[1].lower() not in READABLE:
                per_method[method][1] += 1
                miss_by_method[method].append(p)
        n_miss = sum(m for _, m in per_method.values())
        total_missing += n_miss

        print(f'\n=== {name} ({mode}) : {len(paths)} candidate frames, {n_miss} missing')
        print('  label counts before balancing:', dict(sorted(collections.Counter(labels).items())))
        for m, (n, k) in sorted(per_method.items()):
            print(f'  {m:16s} {n:7d} frames  {"MISSING " + str(k) if k else "ok"}')
        with open(os.path.join(out_dir, f'{name}_missing.txt'), 'w') as f:
            for m, ps in sorted(miss_by_method.items()):
                for p in ps:
                    f.write(f'{m}\t{p}\n')
        bi, bl = ds.balance_dataset(list(paths), list(labels))
        print('  after official balancing:', len(bi), 'frames',
              dict(sorted(collections.Counter(np.asarray(bl).tolist()).items())))
        if paths:
            print('  example path:', paths[0])

    print('\nRESULT:', 'all candidate images present and readable' if total_missing == 0
          else f'{total_missing} images missing or unreadable -- DO NOT TRAIN (see {out_dir})')
    print('Label meaning in NOFE_all test: 0 real, 1 FS, 2 FR, 3 EFS (= unknown for a 3-class NOEFS model).')


if __name__ == '__main__':
    ap = argparse.ArgumentParser()
    sub = ap.add_subparsers(dest='cmd', required=True)
    b = sub.add_parser('build'); b.add_argument('--src', required=True); b.add_argument('--dst', required=True)
    a = sub.add_parser('audit'); a.add_argument('--json', required=True); a.add_argument('--out', required=True)
    a.add_argument('--max_per_cls', type=int, default=13504)
    g = sub.add_parser('gif2png', help='official MidJourney GIF->PNG conversion')
    g.add_argument('--data', default=os.environ.get('DLED_DATA', os.path.expanduser('~/DLED/data')))
    args = ap.parse_args()
    if args.cmd == 'build':
        build(args.src, args.dst)
    elif args.cmd == 'gif2png':
        gif2png(args.data)
    else:
        audit(args.json, args.out, args.max_per_cls)
